'use strict';
const $ = (s,root=document) => root.querySelector(s);
const $$ = (s,root=document) => [...root.querySelectorAll(s)];
const esc = v => String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money = n => new Intl.NumberFormat('fr-FR').format(Number(n)||0);
const norm = s => String(s??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
const icons = {
 arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',up:'<path d="M6 18 18 6M6 6h12v12"/>',
 search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',
 pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',check:'<path d="m5 12 4 4L19 6"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-5"/>',
 design:'<path d="m4 16 1 4 4-1L20 8l-5-5L4 16Z"/><path d="m12 6 5 5M4 20l4-4"/>',code:'<path d="m8 6-6 6 6 6m8-12 6 6-6 6m-3-15-2 18"/>',chart:'<path d="M4 3v17h17M8 15v-4m5 4V7m5 8V4"/>',video:'<rect x="3" y="5" width="14" height="14" rx="2"/><path d="m17 10 5-3v10l-5-3M7 9l5 3-5 3V9Z"/>',
 briefcase:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V3h8v4M3 13h18m-11 0v3h4v-3"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',
 chevron:'<path d="m9 5 7 7-7 7"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',x:'<path d="m6 6 12 12M6 18 18 6"/>',user:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-3a8 8 0 0 1 16 0v3"/>',users:'<path d="M16 21v-2a6 6 0 0 0-12 0v2m16 0v-2a6 6 0 0 0-4-5"/><circle cx="10" cy="6" r="4"/><path d="M16 2a4 4 0 0 1 0 8"/>',
 mail:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',plus:'<path d="M12 4v16M4 12h16"/>',filter:'<path d="M4 6h16M7 12h10m-7 6h4"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',send:'<path d="m22 2-7 20-4-9-9-4L22 2Zm0 0L11 13"/>',logout:'<path d="M9 4H4v16h5m6-13 5 5-5 5M8 12h12"/>'
};
const icon = n => `<svg class="icon" aria-hidden="true" viewBox="0 0 24 24">${icons[n]||icons.arrow}</svg>`;
const arrow = () => icon('arrow');
const brand = () => `<a class="brand" href="#/" aria-label="HerTalent Africa, accueil"><svg class="brand-mark" viewBox="0 0 40 40" aria-hidden="true"><path d="M7 8v24M29 8v24M7 20h22" stroke="currentColor" stroke-width="5" fill="none"/><path d="m18 10 7-7" stroke="currentColor" stroke-width="3"/></svg><span class="brand-name">HerTalent<span>AFRICA</span></span></a>`;
const STORE_KEY='hertalent-africa-v1';
const BACKEND_SESSION_KEY='hertalent-africa-session-token';
const freshState=()=>({accounts:{},activeRole:null,favorites:[],applications:[],missions:[],threads:[],drafts:{},available:true});
let storageOK=true;
function normalizeState(d){if(!d||typeof d!=='object'||Array.isArray(d))return freshState();const s={...freshState(),...d};for(const k of ['favorites','applications','missions','threads'])if(!Array.isArray(s[k]))s[k]=[];if(!s.accounts||typeof s.accounts!=='object')s.accounts={};if(!s.drafts||typeof s.drafts!=='object')s.drafts={};if(!['talent','recruteur'].includes(s.activeRole))s.activeRole=null;return s;}
function readState(){try{return normalizeState(JSON.parse(localStorage.getItem(STORE_KEY)||'null'));}catch{return freshState();}}
let state=readState();
let backendToken=localStorage.getItem(BACKEND_SESSION_KEY)||'';
let backendOnline=false,syncTimer=null;
async function api(path,options={}){const headers={...(options.headers||{})};if(options.body)headers['Content-Type']='application/json';if(backendToken)headers.Authorization=`Bearer ${backendToken}`;const response=await fetch(path,{...options,headers});if(!response.ok)throw new Error(`API ${response.status}`);return response.status===204?null:response.json();}
async function createBackendSession(){const response=await fetch('/api/session',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(!response.ok)throw new Error('Session backend indisponible');const data=await response.json();backendToken=data.token;localStorage.setItem(BACKEND_SESSION_KEY,backendToken);return data;}
async function pushBackendState(){if(!backendToken)return;await api('/api/state',{method:'PUT',body:JSON.stringify({state})});backendOnline=true;}
function scheduleBackendSave(){if(!backendToken)return;clearTimeout(syncTimer);syncTimer=setTimeout(()=>pushBackendState().catch(()=>{backendOnline=false;}),450);}
function save(){try{localStorage.setItem(STORE_KEY,JSON.stringify(state));scheduleBackendSave();}catch{storageOK=false;toast('La sauvegarde locale est indisponible. Les données restent utilisables pendant cette session.');}}
async function bootstrap(){const localState=state;try{const hadSession=Boolean(backendToken);if(!hadSession)await createBackendSession();if(hadSession){const remote=await api('/api/state');state=normalizeState(remote?.state);localStorage.setItem(STORE_KEY,JSON.stringify(state));backendOnline=true;}else await pushBackendState();}catch(error){console.warn('Backend unavailable; local mode remains active.',error);backendOnline=false;if(backendToken){localStorage.removeItem(BACKEND_SESSION_KEY);backendToken='';try{await createBackendSession();state=localState;await pushBackendState();backendOnline=true;}catch(reconnectError){console.warn('Unable to renew the backend session.',reconnectError);}}}render();}
const uid = prefix => `${prefix}-${Date.now()}-${Math.random().toString(36).slice(2,7)}`;
const allMissions=()=>[...state.missions,...MISSIONS];
function allTalents(){const a=state.accounts.talent;if(!a)return TALENTS;return [{id:'mon-profil',name:a.name,title:a.title,category:a.category,city:a.city,country:a.country,photo:null,available:state.available,rate:Number(a.rate),experience:Number(a.experience),languages:['Français'],skills:a.skills.split(',').map(s=>s.trim()).filter(Boolean).slice(0,6),bio:a.bio,projects:[],portfolio:a.portfolio,own:true},...TALENTS];}
const talentById=id=>allTalents().find(t=>t.id===id);
const missionById=id=>allMissions().find(m=>m.id===id);
const dateLabel=iso=>new Date(iso).toLocaleDateString('fr-FR',{day:'numeric',month:'short'});
const currentAccount=()=>state.accounts[state.activeRole];
function routeInfo(){const raw=location.hash.replace(/^#/,'')||'/';const [path,query='']=raw.split('?');return {parts:path.split('/').filter(Boolean),params:new URLSearchParams(query)};}
let filters={q:'',category:'',country:'',available:false,sort:'recommended',mode:'',type:''};
let howRole='recruteur',dashTab='overview',activeThread=null,wizard=null,missionWizard=null,focusReturn=null;
const catIcon=c=>({'Design & création':'design','Développement':'code','Marketing digital':'chart','Data & IA':'chart','Vidéo & animation':'video','Produit & gestion de projet':'briefcase'}[c]||'briefcase');
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),4500);}
function navigate(path){if(location.hash==='#'+path)render();else location.hash=path;}
function renderHeader(){const p=routeInfo().parts[0]||'';$('#header').innerHTML=`<div class="container header">${brand()}<nav class="nav" id="nav" aria-label="Navigation principale"><a class="${p==='talents'?'active':''}" href="#/talents">Trouver un talent</a><a class="${p==='missions'?'active':''}" href="#/missions">Les missions</a><a class="${p==='guide'?'active':''}" href="#/guide">Comment ça marche</a></nav><div class="header-actions"><a class="text-link account-link" href="#/espace">${icon('user')}${currentAccount()?'Mon espace':'Se connecter'}</a><a class="btn small" href="#/publier">Publier une mission ${arrow()}</a><button class="menu-btn" data-action="menu" aria-expanded="false" aria-controls="nav" aria-label="Ouvrir le menu">${icon('menu')}</button></div></div>`;}
function renderFooter(){$('#footer').innerHTML=`<div class="container footer"><div class="footer-top"><div>${brand()}<p>Des compétences, des connexions, des possibilités. Le numérique africain se construit aussi au féminin.</p></div><div class="footer-links"><div><strong>Explorer</strong><a href="#/talents">Les talents</a><a href="#/missions">Les missions</a><a href="#/guide">Comment ça marche</a></div><div><strong>Passer à l’action</strong><a href="#/inscription/talent">Devenir talent</a><a href="#/inscription/recruteur">Rejoindre les recruteurs</a><a href="#/publier">Publier une mission</a></div><div><strong>HerTalent Africa</strong><a href="#/a-propos">Notre ambition</a><a href="#/confidentialite">Confidentialité</a><button class="reset" style="text-align:left" data-action="about-demo">À propos du prototype</button></div></div></div><div class="footer-bottom"><span>© 2026 HerTalent Africa. Le talent a de l’avenir.</span><span>Prototype privé · Données d’exemple · Aucune transaction réelle</span></div></div>`;}
function status(t){return `<span class="status ${t.available?'':'busy'}">${t.available?'Disponible':'Bientôt disponible'}</span>`;}
function portrait(t,extra=''){return t.photo?`<img ${extra} src="assets/${esc(t.photo)}.jpg" alt="Portrait illustratif du profil de ${esc(t.name)}" loading="lazy">`:`<div class="photo-initials" ${extra}>${esc(t.name.split(' ').map(x=>x[0]).slice(0,2).join(''))}</div>`;}
function tags(list){return `<div class="tags">${list.map(x=>`<span class="tag">${esc(x)}</span>`).join('')}</div>`;}
function talentCard(t){const saved=state.favorites.includes(t.id);return `<article class="talent-card"><div class="talent-photo"><a href="#/talent/${esc(t.id)}" tabindex="-1" aria-hidden="true">${portrait(t)}</a><button class="favorite ${saved?'saved':''}" data-action="favorite" data-id="${esc(t.id)}" aria-label="${saved?'Retirer':'Ajouter'} ${esc(t.name)} ${saved?'des':'aux'} favoris" aria-pressed="${saved}">${icon('heart')}</button>${status(t)}</div><div class="talent-body"><div class="talent-name-row"><h3><a href="#/talent/${esc(t.id)}">${esc(t.name)}</a></h3><span class="country-label">${icon('pin')}${esc(t.city)}</span></div><p class="talent-title">${esc(t.title)}</p>${tags(t.skills)}<div class="talent-bottom"><div><strong>${money(t.rate)} FCFA</strong><span> / jour indicatif</span></div><a class="text-link" href="#/talent/${esc(t.id)}">Voir le profil ${icon('up')}</a></div></div></article>`;}
function budget(m){return `${money(m.min)} – ${money(m.max)} FCFA${esc(m.period||'')}`;}
function missionCard(m){return `<article class="mission-card"><div class="mission-top"><span class="company-mark ${esc(m.color)}">${esc(m.letter)}</span><div><strong>${esc(m.company)}</strong><small>${m.local?'Votre mission de démonstration':esc(m.age)+' · Exemple'}</small></div></div><h3><a href="#/mission/${esc(m.id)}">${esc(m.title)}</a></h3>${tags(m.skills)}<p>${esc(m.description.length>150?m.description.slice(0,147)+'…':m.description)}</p><div class="mission-meta"><span>${icon('pin')}${esc(m.country)}</span><span>${icon('globe')}${esc(m.mode)}</span><span>${icon('clock')}${esc(m.duration)}</span></div><div class="mission-bottom"><div><strong>${budget(m)}</strong><small>${esc(m.type)}</small></div><a class="text-link" href="#/mission/${esc(m.id)}">Voir la mission ${arrow()}</a></div></article>`;}
function howSteps(){const r=howRole==='recruteur';return `<div class="switch" role="group" aria-label="Choisir un parcours"><button data-action="how" data-role="recruteur" class="${r?'selected':''}" aria-pressed="${r}">Je recrute</button><button data-action="how" data-role="talent" class="${!r?'selected':''}" aria-pressed="${!r}">Je suis un talent</button></div><div class="steps">${(r?[
['Exprimez votre besoin','Décrivez votre projet, votre budget et vos délais pour poser les bonnes bases.'],['Rencontrez le bon talent','Explorez les profils, les réalisations et échangez sur votre projet.'],['Construisez ensemble','Comparez les propositions et convenez des modalités de votre collaboration.']]:[
['Montrez votre savoir-faire','Créez votre profil, présentez vos compétences et vos réalisations.'],['Trouvez votre prochaine mission','Repérez les opportunités adaptées à votre métier et envoyez une proposition.'],['Faites avancer votre carrière','Échangez avec les recruteurs et construisez des collaborations durables.']]).map(([title,copy],i)=>`<div><span class="step-number">0${i+1}</span><h3>${title}</h3><p>${copy}</p></div>`).join('')}</div>`;}
function home(){return `<div class="container"><section class="hero"><div><div class="eyebrow">Les femmes qui font le numérique africain</div><h1>Le talent est là.<br>L’avenir <span class="serif">aussi.</span></h1><p class="intro">Design, code, data, création. Rencontrez les professionnelles africaines qui donneront une nouvelle dimension à vos projets.</p><div class="hero-actions"><a class="btn clay" href="#/talents">Trouver mon talent ${arrow()}</a><a class="btn outline" href="#/inscription/talent">Je suis un talent ${icon('up')}</a></div><div class="hero-note">${icon('globe')}Des connexions locales. Des ambitions sans frontières.</div></div><div class="hero-art"><div class="art-back"></div><img class="hero-portrait" src="assets/fatou.jpg" alt="Portrait illustratif d’une professionnelle africaine" fetchpriority="high"><div class="floating-tag"><span class="icon-wrap">${icon('check')}</span><div><strong>Votre prochain talent est ici.</strong><small>Compétences, portfolio, ambition.</small></div></div><img class="hero-mini" src="assets/hero.jpg" alt="Une professionnelle du numérique dans un environnement technique"><a class="portrait-caption" href="#/talent/fatou"><span class="arrow">${icon('up')}</span><strong>Fatou Ndiaye</strong><small>Développeuse full stack · Dakar</small></a><span class="art-label">DES TALENTS. TOUT UN CONTINENT.</span></div></section><div class="disciplines"><span>TOUTES LES EXPERTISES,<br>UNE MÊME AMBITION.</span>${CATEGORIES.slice(0,5).map(c=>`<a href="#/talents?metier=${encodeURIComponent(c)}">${icon(catIcon(c))}${esc(c)}</a>`).join('')}</div></div><section class="section section-white"><div class="container"><div class="section-head"><div><div class="eyebrow">Des savoir-faire à découvrir</div><h2>Votre projet mérite <span class="serif">son talent.</span></h2><p>Des profils, des parcours et des réalisations qui parlent d’eux-mêmes.</p></div><a class="text-link" href="#/talents">Explorer tous les talents ${arrow()}</a></div><div class="talent-grid home-grid">${TALENTS.slice(0,3).map(talentCard).join('')}</div><p class="small muted" style="margin-top:17px">Sélection de profils fictifs pour explorer la plateforme. Photographies d’illustration.</p></div></section><section class="section"><div class="container how-grid"><div><div class="eyebrow">De la rencontre à la collaboration</div><h2>Le bon lien.<br>Le bon <span class="serif">élan.</span></h2><p class="muted">Une rencontre peut faire avancer un projet. Ou donner une nouvelle direction à une carrière.</p><a class="text-link" style="margin-top:22px" href="#/guide">Découvrir le fonctionnement ${arrow()}</a></div><div id="how-content">${howSteps()}</div></div></section><section class="section section-white"><div class="container"><div class="section-head"><div><div class="eyebrow">Des projets qui n’attendent que vous</div><h2>La prochaine étape <span class="serif">commence ici.</span></h2><p>Missions ponctuelles ou collaborations durables, trouvez votre place.</p></div><a class="text-link" href="#/missions">Toutes les missions ${arrow()}</a></div><div class="mission-preview">${MISSIONS.slice(0,2).map(missionCard).join('')}</div></div></section><div class="container" style="padding-top:65px"><section class="bottom-cta"><div><h2>Votre savoir-faire a sa place ici.</h2><p>Faites découvrir votre travail, rencontrez de nouvelles équipes et ouvrez le champ des possibles.</p></div><a class="btn white" href="#/inscription/talent">Créer mon profil talent ${arrow()}</a></section></div>`;}
const options=(list,value,all)=>`<option value="">${esc(all)}</option>${list.map(v=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(v)}</option>`).join('')}`;
function field(name,label,type='text',value='',extra=''){return `<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;}
function selectField(name,label,list,value='',empty='Choisir une option',extra=''){return `<div class="field"><label for="${name}">${label}</label><select id="${name}" name="${name}" ${extra}>${options(list,value,empty)}</select></div>`;}
function textareaField(name,label,value='',extra=''){return `<div class="field"><label for="${name}">${label}</label><textarea id="${name}" name="${name}" ${extra}>${esc(value)}</textarea></div>`;}
function empty(iconName,title,copy,action=''){return `<div class="empty">${icon(iconName)}<h3>${title}</h3><p>${copy}</p>${action}</div>`;}
function pageTop(eyebrow,title,copy){return `<div class="container page-top"><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${copy}</p></div>`;}
function listing(isMission=false){const noun=isMission?'missions':'talents';return `${pageTop(isMission?'Votre prochain défi':'Votre prochaine collaboration',isMission?'Des missions à la hauteur de vos ambitions.':'De l’expertise. Et des perspectives.','Explorez '+(isMission?'des opportunités dans le numérique africain. Des exemples concrets pour tester votre candidature.':'les métiers du numérique, découvrez les réalisations et trouvez le profil adapté à votre projet.'))}<div class="container page-layout"><aside class="filter-panel" id="filters" aria-label="Filtres de recherche"><div class="filter-heading">Affiner la recherche <button class="reset" data-action="reset-filters">Réinitialiser</button></div>${selectField('filter-category','Expertise',CATEGORIES,filters.category,'Toutes les expertises','data-filter="category"')}${selectField('filter-country','Pays',COUNTRIES,filters.country,'Tous les pays','data-filter="country"')}${isMission?`${selectField('filter-mode','Mode de travail',['À distance','Hybride','Sur place'],filters.mode,'Tous les modes','data-filter="mode"')}${selectField('filter-type','Collaboration',['Mission freelance','Collaboration longue','CDI / CDD'],filters.type,'Tous les types','data-filter="type"')}`:`<label class="checkbox"><input type="checkbox" data-filter="available" ${filters.available?'checked':''}>Disponibles maintenant</label>`}<div class="tip-box">${icon('info')} ${isMission?'Un bon brief précise les livrables, le budget et les délais.':'Le portfolio vous aide à comprendre l’approche et les compétences d’un talent.'}</div></aside><div><div class="search-box">${icon('search')}<input type="search" id="search" aria-label="Rechercher des ${noun}" placeholder="${isMission?'Un mot-clé, une compétence, un projet…':'Un métier, une compétence, un prénom…'}" value="${esc(filters.q)}" autocomplete="off"></div><div class="result-bar"><span id="result-count" aria-live="polite"></span><button class="btn outline small filter-toggle" data-action="filters" aria-expanded="false" aria-controls="filters">${icon('filter')}Filtres</button><label><span class="small muted">Trier : </span><select data-filter="sort" aria-label="Trier les résultats"><option value="recommended" ${filters.sort==='recommended'?'selected':''}>${isMission?'Plus récentes':'Sélection HerTalent'}</option><option value="name" ${filters.sort==='name'?'selected':''}>${isMission?'Titre A → Z':'Prénom A → Z'}</option><option value="rate" ${filters.sort==='rate'?'selected':''}>${isMission?'Budget croissant':'Tarif croissant'}</option></select></label></div><div id="results"></div><p class="small muted" style="margin-top:22px">${isMission?'Missions fictives et simulations créées dans ce navigateur.':'Profils fictifs · Tarifs indicatifs de démonstration, à convenir pour chaque projet.'}</p></div></div>`;}
function filterTalents(f=filters){let list=allTalents().filter(t=>(!f.category||t.category===f.category)&&(!f.country||t.country===f.country)&&(!f.available||t.available)&&(!f.q||norm([t.name,t.title,t.city,t.country,...t.skills].join(' ')).includes(norm(f.q))));if(f.sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name,'fr'));if(f.sort==='rate')list.sort((a,b)=>a.rate-b.rate);return list;}
function filterMissions(f=filters){let list=allMissions().filter(m=>(!f.category||m.category===f.category)&&(!f.country||m.country===f.country)&&(!f.mode||m.mode===f.mode)&&(!f.type||m.type===f.type)&&(!f.q||norm([m.title,m.company,m.description,...m.skills].join(' ')).includes(norm(f.q))));if(f.sort==='name')list.sort((a,b)=>a.title.localeCompare(b.title,'fr'));if(f.sort==='rate')list.sort((a,b)=>a.min-b.min);return list;}
function updateResults(){const isMission=routeInfo().parts[0]==='missions';const list=isMission?filterMissions():filterTalents();$('#result-count').textContent=`${list.length} ${isMission?'mission':'talent'}${list.length>1?'s':''} ${list.length>1?'à découvrir':'à découvrir'}`;$('#results').innerHTML=list.length?`<div class="${isMission?'mission-list':'talent-grid'}">${list.map(isMission?missionCard:talentCard).join('')}</div>`:empty('search','Aucun résultat pour cette recherche.','Essayez un autre mot-clé ou élargissez vos filtres.',`<button class="btn outline" data-action="reset-filters">Réinitialiser les filtres ${arrow()}</button>`);}
function projectArt(p){return `<div class="portfolio-art ${esc(p.art)}">${p.art==='design'?`<div class="mock-ui"><b>${esc(p.word)}</b><small>Un quotidien plus simple.</small><i></i><i></i><span>Découvrir →</span></div>`:p.art==='data'?`<div><span class="project-word" style="font-size:23px">${esc(p.word)}</span><div class="mini-bars">${[43,67,52,90,104].map(v=>`<i style="height:${v}px"></i>`).join('')}</div></div>`:`<div class="project-word">${esc(p.word)}<small>${p.art==='code'?'BUILDING WHAT’S NEXT':'PENSÉ POUR DEMAIN'}</small></div>`}</div>`;}
function profile(id){const t=talentById(id);if(!t)return notFound();return `<div class="container page-top"><div class="breadcrumb"><a href="#/talents">Les talents</a>${icon('chevron')}<span>${esc(t.name)}</span></div></div><div class="container profile-layout"><div><section class="panel"><div class="profile-header">${t.photo?`<img class="profile-avatar" src="assets/${t.photo}.jpg" alt="Portrait illustratif de ${esc(t.name)}">`:`<div class="profile-avatar photo-initials">${esc(t.name[0])}</div>`}<div>${status(t)}<h1>${esc(t.name)}</h1><p class="profile-role">${esc(t.title)}</p><div class="inline-meta"><span>${icon('pin')}${esc(t.city)}, ${esc(t.country)}</span><span>${icon('briefcase')}${t.experience} ans d’expérience</span></div></div></div><nav class="profile-subnav" aria-label="Sections du profil"><a href="#" data-scroll="profile-portfolio">Réalisations</a><a href="#" data-scroll="profile-about">À propos</a><a href="#" data-scroll="profile-skills">Compétences</a></nav><div id="profile-portfolio"><h2>Le savoir-faire en images</h2><div class="portfolio-grid">${t.projects.map((p,i)=>`<button class="portfolio-item" data-action="project" data-id="${t.id}" data-index="${i}" aria-label="Ouvrir ${esc(p.title)}">${projectArt(p)}<span class="caption">${esc(p.title)}<small>${esc(p.type)} ${icon('up')}</small></span></button>`).join('')}</div></div></section><section class="panel" id="profile-about"><h2>À propos de ${esc(t.name.split(' ')[0])}</h2><p>${esc(t.bio)}</p><div class="two-column" style="margin-top:24px"><div><h3 style="font-size:14px;margin-bottom:10px">Méthode de collaboration</h3><p style="font-size:12px">Cadrage du besoin, proposition détaillée, points d’étape réguliers et livraison documentée.</p></div><div><h3 style="font-size:14px;margin-bottom:10px">Langues de travail</h3>${tags(t.languages)}</div></div></section><section class="panel" id="profile-skills"><h2>Compétences & outils</h2>${tags([...t.skills,t.category])}</section></div><aside class="profile-side"><section class="panel"><div class="small muted">Tarif journalier indicatif</div><div class="price">${money(t.rate)} <small>FCFA / jour</small></div><p style="font-size:11px">Un devis adapté à votre projet reste à convenir.</p><hr class="side-divider"><div class="side-detail"><span>Localisation</span><strong>${esc(t.city)}</strong></div><div class="side-detail"><span>Collaboration</span><strong>À distance / hybride</strong></div><div class="side-detail"><span>Expérience</span><strong>${t.experience} ans</strong></div><div class="side-actions"><button class="btn clay" data-action="contact" data-id="${t.id}">Proposer une mission ${arrow()}</button><button class="btn outline" data-action="favorite" data-id="${t.id}" aria-pressed="${state.favorites.includes(t.id)}">${icon('heart')}${state.favorites.includes(t.id)?'Retirer de ma sélection':'Ajouter à ma sélection'}</button></div></section><div class="demo-note">${icon('info')}Profil et réalisations fictifs. Les photographies illustrent le prototype et ne représentent pas des membres inscrites. Les messages sont simulés dans ce navigateur.</div></aside></div>`;}
function missionDetail(id){const m=missionById(id);if(!m)return notFound();const applied=state.applications.some(a=>a.missionId===m.id);return `<div class="container page-top"><div class="breadcrumb"><a href="#/missions">Les missions</a>${icon('chevron')}<span>${esc(m.category)}</span></div></div><div class="container detail-grid"><article class="panel mission-detail"><div class="mission-top"><span class="company-mark ${esc(m.color)}">${esc(m.letter)}</span><div><strong>${esc(m.company)}</strong><small>${m.local?'Votre mission de démonstration':'Entreprise fictive · '+esc(m.age)}</small></div></div><h1>${esc(m.title)}</h1>${tags(m.skills)}<div class="inline-meta"><span>${icon('pin')}${esc(m.city)}, ${esc(m.country)}</span><span>${icon('globe')}${esc(m.mode)}</span><span>${icon('clock')}${esc(m.duration)}</span></div><div class="detail-section"><h2>Le projet</h2><p>${esc(m.description)}</p></div><div class="detail-section"><h2>Les livrables attendus</h2><ul>${m.deliverables.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div class="detail-section"><h2>Le profil recherché</h2><p>${esc(m.requirements)}</p></div><div class="notice">Avant de commencer, convenez du périmètre, du calendrier et des conditions de paiement par écrit.</div></article><aside class="profile-side"><section class="panel"><span class="status">Ouverte aux propositions</span><div class="small muted" style="margin-top:22px">Budget prévu ${m.period?'(mensuel)':''}</div><h2 style="font-size:22px;line-height:1.5;margin-top:6px">${budget(m)}</h2><hr class="side-divider"><div class="side-detail"><span>Type</span><strong>${esc(m.type)}</strong></div><div class="side-detail"><span>Durée</span><strong>${esc(m.duration)}</strong></div><div class="side-detail"><span>Mode</span><strong>${esc(m.mode)}</strong></div><div class="side-actions">${m.local&&state.activeRole!=='talent'?'<a class="btn clay" href="#/espace">Gérer ma mission '+arrow()+'</a>':`<button class="btn clay" data-action="apply" data-id="${m.id}" ${applied?'disabled':''}>${applied?'Proposition envoyée':`Envoyer une proposition ${arrow()}`}</button>`}<a class="btn outline" href="#/guide">Comprendre le parcours</a></div></section><div class="demo-note">${icon('info')}${m.local?'Cette mission est conservée uniquement dans votre navigateur.':'Cette mission sert à tester le parcours. Aucune offre d’emploi réelle n’est publiée et aucune candidature n’est transmise à un tiers.'}</div></aside></div>`;}
function progress(step,labels){return `<div class="progress" aria-label="Étape ${step} sur ${labels.length}">${labels.map((label,i)=>`<div class="${i<step?'done':''}"><span class="line"></span><small>0${i+1} · ${label}</small></div>`).join('')}</div>`;}
function accountChoice(){return `${pageTop('Un espace pour avancer','Votre prochaine collaboration commence ici.','Choisissez votre parcours pour découvrir les fonctionnalités. Dans cette version privée, les espaces sont sauvegardés uniquement sur cet appareil.')}<div class="container form-wrap" style="padding-top:0"><div class="choice-grid">${[['talent','user','Je suis un talent','Mettez vos compétences en lumière, candidatez aux missions et suivez vos propositions.'],['recruteur','briefcase','Je recrute','Repérez les bons profils, publiez votre besoin et démarrez une conversation.']].map(([role,ic,title,copy])=>`<div class="choice-card"><span class="icon-wrap">${icon(ic)}</span><h2>${title}</h2><p>${copy}</p>${state.accounts[role]?`<button class="btn" data-action="switch-role" data-role="${role}">Reprendre mon espace ${arrow()}</button><p style="margin:10px 0 0;font-size:10px">${esc(state.accounts[role].name)} · Espace local existant</p>`:`<a class="text-link" href="#/inscription/${role}">Créer mon espace ${arrow()}</a>`}</div>`).join('')}</div><div class="demo-note">${icon('info')}L’inscription sert à tester le parcours. Aucun compte en ligne, mot de passe ou système de connexion réel n’est créé.</div></div>`;}
function initSignup(role){if(!wizard||wizard.role!==role)wizard={role,step:1,data:{...(state.drafts['signup-'+role]||state.accounts[role]||{})}};}
function signup(role){if(!['talent','recruteur'].includes(role))return accountChoice();initSignup(role);const t=role==='talent',d=wizard.data,s=wizard.step;let body='';if(s===1){body=`<h2>${t?'Faisons connaissance.':'Présentez votre entreprise.'}</h2><p class="form-intro">${t?'Votre profil commence par quelques informations essentielles.':'Donnons un visage aux projets que vous portez.'}</p><div class="form-grid">${field('name','Nom et prénom *','text',d.name,'required minlength="2" maxlength="80" autocomplete="name" placeholder="Ex. : Amina Adéoti"')}${field('email','Adresse e-mail *','email',d.email,'required maxlength="120" autocomplete="email" placeholder="vous@exemple.com"')}${!t?field('company','Entreprise / organisation *','text',d.company,'required minlength="2" maxlength="80" placeholder="Le nom de votre structure"'):selectField('category','Votre expertise principale *',CATEGORIES,d.category,'Choisir une expertise','required')}${field('title',t?'Votre métier *':'Votre fonction *','text',d.title,`required minlength="3" maxlength="90" placeholder="${t?'Ex. : Product designer UX/UI':'Ex. : Fondatrice, responsable RH…'}"`)}${selectField('country','Pays *',COUNTRIES,d.country,'Choisir un pays','required')}${field('city','Ville *','text',d.city,'required minlength="2" maxlength="80" placeholder="Ex. : Cotonou"')}</div>`;}else if(s===2){body=`<h2>${t?'Ce qui fait votre différence.':'Votre besoin, en quelques mots.'}</h2><p class="form-intro">${t?'Aidez les recruteurs à comprendre votre profil et votre façon de travailler.':'Ces informations personnaliseront votre espace recruteur.'}</p>${textareaField('bio',t?'Présentez votre savoir-faire *':'Présentez votre organisation *',d.bio,'required minlength="30" maxlength="1500" placeholder="Votre spécialité, votre approche et les projets qui vous motivent…"')}<div class="form-grid">${t?`${field('skills','Vos compétences clés *','text',d.skills,'required minlength="2" maxlength="150" placeholder="Figma, recherche UX, design system…"')}${field('rate','Tarif indicatif / jour (FCFA) *','number',d.rate,'required min="1000" max="5000000" step="1000" placeholder="65000"')}${field('experience','Années d’expérience *','number',d.experience,'required min="0" max="50" step="1" placeholder="3"')}${selectField('availability','Disponibilité *',['Disponible maintenant','Bientôt disponible'],d.availability,'Choisir une disponibilité','required')}`:`${selectField('sector','Secteur d’activité *',['Technologie','Commerce','Éducation','Santé','Culture & médias','Association / ONG','Services','Autre secteur'],d.sector,'Choisir un secteur','required')}${selectField('need','Votre recherche principale *',['Une mission ponctuelle','Une collaboration durable','Un recrutement CDI / CDD','Explorer les talents'],d.need,'Choisir un besoin','required')}`}</div>${t?field('portfolio','Lien de portfolio (facultatif)','url',d.portfolio,'maxlength="500" placeholder="https://votre-portfolio.com"'):''}`;}else{body=`<h2>Tout commence avec ce profil.</h2><p class="form-intro">Vérifiez vos informations avant d’activer votre espace de démonstration.</p><div class="review"><h3>${esc(d.name)}</h3><dl><dt>${t?'Métier':'Organisation'}</dt><dd>${esc(t?d.title:d.company)}</dd><dt>Localisation</dt><dd>${esc(d.city)}, ${esc(d.country)}</dd><dt>Contact</dt><dd>${esc(d.email)}</dd>${t?`<dt>Expertise</dt><dd>${esc(d.category)}</dd><dt>Tarif indicatif</dt><dd>${money(d.rate)} FCFA / jour</dd><dt>Compétences</dt><dd>${esc(d.skills)}</dd>`:''}<dt>Présentation</dt><dd>${esc(d.bio)}</dd></dl></div><label class="checkbox" style="margin-top:23px;align-items:start"><input type="checkbox" name="consent" required>Je comprends que cet espace est une simulation locale et que mes informations ne sont pas publiées.</label>`;}return `<div class="container form-wrap"><div class="form-heading"><div class="eyebrow" style="justify-content:center">${t?'Votre talent mérite d’être vu':'Les bons projets commencent par une rencontre'}</div><h1>${t?'Faites place à votre talent.':'Faites avancer vos projets.'}</h1><p>${t?'Un profil, vos réalisations, de nouvelles possibilités.':'Un espace pour trouver et rencontrer vos futures collaboratrices.'}</p></div><form class="form-card" id="signup-form">${progress(s,['L’essentiel',t?'Votre expertise':'Votre organisation','Votre espace'])}${body}<div id="form-error" role="alert"></div><div class="form-actions">${s>1?'<button class="text-link" type="button" data-action="signup-back">'+icon('back')+' Retour</button>':'<a class="text-link" href="#/inscription">'+icon('back')+' Changer de rôle</a>'}<button class="btn clay" type="submit">${s===3?'Créer mon espace démo':'Continuer'} ${arrow()}</button></div></form><div class="demo-note" style="margin-top:17px">${icon('info')}Démonstration privée : aucune inscription réelle, aucun e-mail envoyé. Vous pourrez effacer vos données depuis votre espace.</div></div>`;}
function mergeFormData(form,target){for(const [k,v] of new FormData(form).entries())target[k]=typeof v==='string'?v.trim():v;}
function validWebsite(value){if(!value)return true;try{return ['https:','http:'].includes(new URL(value).protocol);}catch{return false;}}
function validateSignup(d,role){if(!d.name||d.name.length<2||!d.email||!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(d.email)||!COUNTRIES.includes(d.country)||!d.city||!d.title)return 'Complétez les informations essentielles du profil.';if(!d.bio||d.bio.length<30)return 'La présentation doit contenir au moins 30 caractères.';if(role==='talent'&&(!CATEGORIES.includes(d.category)||!d.skills||Number(d.rate)<1000||Number(d.rate)>5000000||!Number.isFinite(Number(d.rate))||!Number.isInteger(Number(d.experience))||Number(d.experience)<0||Number(d.experience)>50||!d.availability))return 'Vérifiez vos compétences, votre tarif, votre expérience et votre disponibilité.';if(role==='recruteur'&&(!d.company||!d.sector||!d.need))return 'Complétez les informations de votre organisation.';if(!validWebsite(d.portfolio))return 'Le portfolio doit être une adresse Web commençant par https:// ou http://.';return '';}
function submitSignup(form){if(!form.reportValidity())return;mergeFormData(form,wizard.data);state.drafts['signup-'+wizard.role]=wizard.data;save();if(wizard.step<3){wizard.step++;render(false);return;}const error=validateSignup(wizard.data,wizard.role);if(error){showFormError(error);return;}state.accounts[wizard.role]={...wizard.data,createdAt:new Date().toISOString()};state.activeRole=wizard.role;if(wizard.role==='talent')state.available=wizard.data.availability==='Disponible maintenant';delete state.drafts['signup-'+wizard.role];const next=state.drafts.next||'/espace';delete state.drafts.next;save();wizard=null;dashTab='overview';navigate(next);toast('Votre espace de démonstration est prêt.');}
function initMissionWizard(){if(!missionWizard)missionWizard=state.drafts.mission||{step:1,data:{}};}
function publishPage(){initMissionWizard();const {step:s,data:d}=missionWizard;let body='';if(s===1){body=`<h2>Quel projet voulez-vous faire avancer ?</h2><p class="form-intro">Un brief précis facilite les bonnes rencontres.</p>${field('title','Titre de la mission *','text',d.title,'required minlength="10" maxlength="120" placeholder="Ex. : Concevoir notre application de livraison"')}${selectField('category','Expertise recherchée *',CATEGORIES,d.category,'Choisir une expertise','required')}${textareaField('description','Décrivez le contexte et votre objectif *',d.description,'required minlength="50" maxlength="3000" placeholder="Quel problème voulez-vous résoudre ? À qui s’adresse votre projet ?"')}${textareaField('deliverables','Livrables attendus *',d.deliverables,'required minlength="10" maxlength="1500" placeholder="Un livrable par ligne : maquettes, prototype, site de 5 pages…"')}${textareaField('requirements','Compétences et profil recherchés *',d.requirements,'required minlength="20" maxlength="1500" placeholder="Expérience, outils, compétences…"')}`;}else if(s===2){body=`<h2>Posons un cadre clair.</h2><p class="form-intro">Des conditions lisibles pour permettre aux talents de se positionner.</p><div class="form-grid">${selectField('type','Type de collaboration *',['Mission freelance','Collaboration longue','CDI / CDD'],d.type,'Choisir un type','required')}${field('duration','Durée prévue *','text',d.duration,'required minlength="2" maxlength="60" placeholder="Ex. : 3 à 4 semaines"')}${field('min','Budget minimum (FCFA) *','number',d.min,'required min="10000" max="100000000" step="1000" placeholder="250000"')}${field('max','Budget maximum (FCFA) *','number',d.max,'required min="10000" max="100000000" step="1000" placeholder="400000"')}${selectField('period','Ce budget correspond à *',['Au projet','Par mois'],d.period,'Choisir une base','required')}${selectField('mode','Mode de travail *',['À distance','Hybride','Sur place'],d.mode,'Choisir un mode','required')}${selectField('country','Pays de l’organisation *',COUNTRIES,d.country,'Choisir un pays','required')}${field('city','Ville *','text',d.city,'required minlength="2" maxlength="80" placeholder="Cotonou"')}</div>${field('skills','Mots-clés / outils *','text',d.skills,'required minlength="2" maxlength="180" placeholder="Figma, UX/UI, prototype…"')}`;}else{body=`<h2>Votre mission, avant de la partager.</h2><p class="form-intro">Elle sera ajoutée aux missions de ce navigateur, sans publication sur un marché réel.</p><div class="review"><h3>${esc(d.title)}</h3><dl><dt>Expertise</dt><dd>${esc(d.category)}</dd><dt>Budget</dt><dd>${money(d.min)} – ${money(d.max)} FCFA${d.period==='Par mois'?' / mois':' au projet'}</dd><dt>Collaboration</dt><dd>${esc(d.type)} · ${esc(d.duration)}</dd><dt>Localisation</dt><dd>${esc(d.city)}, ${esc(d.country)} · ${esc(d.mode)}</dd><dt>Le projet</dt><dd>${esc(d.description)}</dd><dt>Livrables</dt><dd style="white-space:pre-line">${esc(d.deliverables)}</dd></dl></div>${state.accounts.recruteur?`<p class="small muted" style="margin-top:17px">Mission portée par ${esc(state.accounts.recruteur.company)}.</p><label class="checkbox" style="margin-top:18px"><input name="consent" type="checkbox" required>Ajouter cette mission à ma démonstration privée.</label>`:`<div class="notice">Créez votre espace recruteur pour conserver et gérer cette mission. Votre brief est déjà sauvegardé.</div>`}`;}const accountReady=!!state.accounts.recruteur;return `<div class="container form-wrap"><div class="form-heading"><div class="eyebrow" style="justify-content:center">Une mission. De nouvelles possibilités.</div><h1>Donnez de l’élan à votre projet.</h1><p>Décrivez votre besoin et préparez votre prochaine collaboration.</p></div><form class="form-card" id="publish-form">${progress(s,['Votre projet','Les conditions','Vérification'])}${body}<div id="form-error" role="alert"></div><div class="form-actions">${s>1?'<button type="button" class="text-link" data-action="mission-back">'+icon('back')+' Retour</button>':'<span class="hint">Votre brouillon est sauvegardé à chaque étape.</span>'}${s===3&&!accountReady?`<button type="button" class="btn clay" data-action="start-account" data-role="recruteur" data-next="/publier">Créer mon espace ${arrow()}</button>`:`<button class="btn clay" type="submit">${s===3?'Publier dans la démo':'Continuer'} ${arrow()}</button>`}</div></form><div class="demo-note" style="margin-top:17px">${icon('info')}Tous les montants sont en FCFA. Aucun paiement ni abonnement n’est activé.</div></div>`;}
function validateMission(d){if(!d.title||d.title.length<10||!CATEGORIES.includes(d.category)||!d.description||d.description.length<50||!d.deliverables||d.deliverables.length<10||!d.requirements||d.requirements.length<20)return 'Complétez le titre, la description, les livrables et le profil recherché.';const min=Number(d.min),max=Number(d.max);if(!Number.isFinite(min)||!Number.isFinite(max)||min<10000||max>100000000||max<min)return 'Le budget maximum doit être supérieur ou égal au minimum (au moins 10 000 FCFA).';if(!COUNTRIES.includes(d.country)||!d.city||!d.duration||!['À distance','Hybride','Sur place'].includes(d.mode)||!['Mission freelance','Collaboration longue','CDI / CDD'].includes(d.type)||!['Au projet','Par mois'].includes(d.period)||!d.skills)return 'Complétez les conditions de la mission.';return '';}
function submitMission(form){if(!form.reportValidity())return;mergeFormData(form,missionWizard.data);const d=missionWizard.data;if(missionWizard.step===2&&Number(d.max)<Number(d.min)){showFormError('Le budget maximum ne peut pas être inférieur au minimum.');return;}if(missionWizard.step<3){missionWizard.step++;state.drafts.mission=missionWizard;save();render(false);return;}const err=validateMission(d);if(err){showFormError(err);return;}if(!state.accounts.recruteur){showFormError('Créez d’abord un espace recruteur.');return;}const m={...d,id:uid('mission'),company:state.accounts.recruteur.company,letter:state.accounts.recruteur.company.charAt(0).toUpperCase(),color:'clay',skills:d.skills.split(',').map(s=>s.trim()).filter(Boolean).slice(0,6),deliverables:d.deliverables.split('\n').map(s=>s.trim()).filter(Boolean),min:Number(d.min),max:Number(d.max),period:d.period==='Par mois'?' / mois':'',age:'À l’instant',local:true,createdAt:new Date().toISOString()};state.missions.unshift(m);state.activeRole='recruteur';delete state.drafts.mission;missionWizard=null;save();navigate('/mission/'+m.id);toast('Votre mission est ajoutée à la démonstration privée.');}
function showFormError(s){const el=$('#form-error');if(el){el.innerHTML=`<div class="error">${esc(s)}</div>`;el.scrollIntoView({block:'nearest',behavior:'smooth'});}}
function guide(){return `${pageTop('Le lien entre ambition et opportunités','Deux parcours. Une même envie d’avancer.','Testez une collaboration de bout en bout : du premier profil à la proposition, sans quitter cette version privée.')}<div class="container"><div class="guide-grid"><section class="guide-card"><span class="eyebrow">Pour les recruteurs</span><h2>Rencontrez votre prochaine collaboratrice.</h2><ol class="guide-steps"><li><div><b>Définissez votre besoin</b><p>Publiez un brief avec le contexte, les livrables, le budget et les délais.</p></div></li><li><div><b>Explorez les profils</b><p>Filtrez par compétence, pays ou disponibilité. Ouvrez les portfolios et constituez votre sélection.</p></div></li><li><div><b>Engagez la conversation</b><p>Proposez une mission directement à un talent et retrouvez votre message dans votre espace.</p></div></li><li><div><b>Cadrez la collaboration</b><p>Comparez les approches, précisez les attentes et convenez des conditions par écrit.</p></div></li></ol><a class="btn clay" href="#/talents">Commencer par les talents ${arrow()}</a><a class="text-link" href="#/publier" style="display:flex;margin-top:18px">J’ai déjà un projet à publier ${arrow()}</a></section><section class="guide-card"><span class="eyebrow">Pour les talents</span><h2>Faites de votre expertise une opportunité.</h2><ol class="guide-steps"><li><div><b>Créez votre profil</b><p>Présentez votre métier, votre expérience, vos compétences et votre portfolio.</p></div></li><li><div><b>Repérez une mission</b><p>Consultez le brief, les livrables et le budget pour vérifier que le projet vous correspond.</p></div></li><li><div><b>Envoyez une proposition précise</b><p>Expliquez votre approche, proposez un montant en FCFA et indiquez un délai.</p></div></li><li><div><b>Suivez vos échanges</b><p>Retrouvez votre proposition et votre conversation dans votre espace talent.</p></div></li></ol><a class="btn" href="#/inscription/talent">Créer mon profil talent ${arrow()}</a><a class="text-link" href="#/missions" style="display:flex;margin-top:18px">Voir d’abord les missions ${arrow()}</a></section></div><div class="faq"><h2>Les réponses pour bien commencer.</h2>${[
['Quels métiers ont leur place sur HerTalent Africa ?','Les métiers du numérique dans leur diversité : design, développement, marketing digital, data, intelligence artificielle, vidéo, animation, gestion de projet et produit.'],['Dois-je être dans le même pays que le recruteur ?','Les missions peuvent se faire à distance, en mode hybride ou sur place. Chaque fiche précise le pays et les conditions pour que vous puissiez choisir selon votre situation.'],['Comment se passent les paiements ?','Ce prototype ne gère aucun paiement. Il permet de préciser des budgets en FCFA et de simuler les échanges. Pour une future collaboration réelle, le devis, les échéances et les modalités de paiement devront être convenus entre les parties.'],['Est-ce que les profils et les missions sont réels ?','Les profils et missions fournis sont fictifs. Les photos servent d’illustration. Les profils, missions, propositions et messages que vous créez restent sur ce navigateur : aucun tiers ne les reçoit.'],['Quel est le prix de la plateforme ?','Aucun tarif d’accès ou abonnement n’est activé dans cette version de démonstration. Le modèle économique sera défini avant une ouverture réelle.'],['Comment reprendre ou effacer mon essai ?','Utilisez « Mon espace » sur le même navigateur pour retrouver votre session. Dans l’onglet « Mon profil », vous pourrez effacer l’ensemble des données de cette démonstration locale.']].map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></div>`;}
function about(){return `${pageTop('Notre ambition','Le numérique africain se construit aussi au féminin.','HerTalent Africa veut rendre les compétences visibles et faciliter les collaborations qui font avancer les projets.')}<div class="container long-copy"><section class="panel"><h2>Un espace pour montrer ce que l’on sait faire.</h2><p>Le talent se reconnaît dans le travail. La plateforme met donc les compétences, les réalisations et les conditions de collaboration au premier plan. Chaque profil doit aider une entreprise à comprendre une approche, pas simplement à lire un intitulé de poste.</p><h2>Connecter les écosystèmes.</h2><p>De Cotonou à Dakar, de Lomé à Abidjan et au-delà, HerTalent Africa relie les professionnelles du numérique aux entreprises, agences, associations et porteurs de projets. Les collaborations peuvent être locales ou à distance, ponctuelles ou durables.</p><h2>Une première version à éprouver.</h2><p>Cette version privée sert à tester les parcours et affiner le produit avant son ouverture. Son contenu d’exemple ne constitue ni une offre réelle, ni une référence client, ni une communauté déjà constituée.</p><a class="btn clay" href="#/guide">Explorer les parcours ${arrow()}</a></section></div>`;}
function privacy(){return `${pageTop('Données & transparence','Votre essai reste dans votre navigateur.','Cette version est un prototype privé destiné à valider l’expérience de HerTalent Africa.')}<div class="container long-copy"><section class="panel"><h2>Ce que cette démonstration conserve</h2><p>Les profils de simulation, favoris, brouillons, missions, candidatures et messages sont sauvegardés dans le stockage local de votre navigateur. Vous pouvez utiliser des informations fictives pour vos essais. Aucune inscription réelle n’est créée et aucun message n’est envoyé à des tiers.</p><h2>Accès et durée</h2><p>Le site est hébergé avec un accès privé. Les données locales restent disponibles sur le même navigateur jusqu’à leur suppression. Elles ne sont pas synchronisées entre appareils et peuvent être accessibles à une autre personne utilisant ce même profil de navigateur.</p><h2>Effacer les données</h2><p>Depuis « Mon espace », ouvrez « Mon profil » puis « Effacer ma démonstration ». Vous pouvez aussi utiliser le bouton ci-dessous. Cette action efface uniquement les données HerTalent Africa de ce navigateur.</p><button class="btn outline" data-action="reset-demo">Effacer ma démonstration</button><h2>Photographies d’illustration</h2><p>Les noms, métiers, entreprises, réalisations et missions sont fictifs. Les photographies proviennent de banques d’images et ne correspondent pas à des personnes inscrites : <a href="https://unsplash.com/photos/nvvvAy3nhX8" target="_blank" rel="noopener noreferrer" style="text-decoration:underline">Jadon Johnson</a>, <a href="https://unsplash.com/photos/J1Umi-cHllE" target="_blank" rel="noopener noreferrer" style="text-decoration:underline">Arnold Obizzy</a>, <a href="https://unsplash.com" target="_blank" rel="noopener noreferrer" style="text-decoration:underline">Unsplash</a> et <a href="https://nappy.co/photo/wocintech-microsoft-196%2BaIhO0Hz2tRuUIP58gA7m6" target="_blank" rel="noopener noreferrer" style="text-decoration:underline">WOCInTech / Nappy</a>.</p><h2>Services actifs</h2><p>Aucun paiement, suivi publicitaire, envoi d’e-mail ou messagerie externe n’est activé. Les images et la police sont servies avec le site. L’hébergement privé et son contrôle d’accès sont fournis par Sites.</p></section></div>`;}
function notFound(){return `<div class="container section">${empty('search','Cette page est introuvable.','Le lien a peut-être changé. Reprenez votre exploration depuis les talents ou les missions.',`<a class="btn clay" href="#/talents">Explorer les talents ${arrow()}</a>`)}</div>`;}
function myThreads(){return state.threads.filter(t=>t.role===state.activeRole||t.roles?.includes(state.activeRole));}
function threadName(t){return state.activeRole==='recruteur'&&t.recruiterWith?t.recruiterWith:t.with;}
function receivedApplications(){return state.applications.filter(a=>state.missions.some(m=>m.id===a.missionId));}
function receivedView(){const list=receivedApplications();return `<div class="dash-title"><h2>Les propositions reçues</h2><a class="text-link" href="#/guide">Le parcours ${arrow()}</a></div><div class="demo-note" style="margin-bottom:20px">Pour tester la boucle complète : créez une mission, passez côté talent, candidatez à votre mission locale, puis reprenez votre espace recruteur. Seules vos actions alimentent cette liste.</div>${list.length?list.map(ap=>`<section class="panel"><div class="activity-row" style="padding-top:0"><div><strong>${esc(ap.talentName||'Talent de démonstration')}</strong><small>${esc(ap.missionTitle)} · ${dateLabel(ap.createdAt)}</small></div><span class="pill">${ap.status==='selected'?'Profil retenu':'À étudier'}</span></div><div class="inline-meta"><span>${icon('briefcase')}${money(ap.amount)} FCFA</span><span>${icon('clock')}${esc(ap.delay)}</span></div><p style="white-space:pre-wrap;margin:18px 0">${esc(ap.message)}</p><div style="display:flex;gap:12px;flex-wrap:wrap"><button class="btn clay small" data-action="select-applicant" data-id="${esc(ap.id)}" ${ap.status==='selected'?'disabled':''}>${ap.status==='selected'?'Profil retenu':`Retenir ce profil ${icon('check')}`}</button><button class="btn outline small" data-action="open-thread" data-id="${esc(ap.threadId)}">Échanger ${icon('mail')}</button></div></section>`).join(''):empty('send','Vos prochaines rencontres sont ici.','Aucune candidature n’a encore été créée pour vos missions locales. Testez le parcours talent pour faire apparaître une proposition.',`<button class="btn outline" data-action="choose-role">Passer côté talent ${arrow()}</button>`)}`;}
function dashboard(){const a=currentAccount();if(!a)return accountChoice();const talent=state.activeRole==='talent';const tabs=talent?[['overview','grid','Vue d’ensemble'],['applications','send','Mes propositions'],['messages','mail','Messages'],['profile','user','Mon profil']]:[['overview','grid','Vue d’ensemble'],['missions','briefcase','Mes missions'],['received','send','Propositions reçues'],['favorites','heart','Ma sélection'],['messages','mail','Messages'],['profile','user','Mon profil']];if(!tabs.some(t=>t[0]===dashTab))dashTab='overview';return `${pageTop(talent?'Espace talent':'Espace recruteur',`Bonjour, ${esc(a.name.split(' ')[0])}.`,talent?'Vos compétences ouvrent des portes. Retrouvez vos propositions et vos échanges.':'Votre prochain projet prend forme. Retrouvez vos missions, votre sélection et vos échanges.')}<div class="container dashboard"><aside class="dash-nav" aria-label="Navigation de votre espace"><div class="who"><strong>${esc(talent?a.name:a.company)}</strong><small>${talent?'Profil talent':'Espace recruteur'} · Démonstration</small></div>${tabs.map(([id,ic,label])=>`<button data-action="dash-tab" data-tab="${id}" class="${dashTab===id?'active':''}" ${dashTab===id?'aria-current="page"':''}>${icon(ic)}${label}${id==='messages'&&myThreads().length?`<span class="count">${myThreads().length}</span>`:''}</button>`).join('')}<button class="dash-switch" data-action="choose-role">${icon('logout')}Changer de parcours</button></aside><div id="dash-content">${dashContent(talent,a)}</div></div>`;}
function dashContent(talent,a){if(dashTab==='overview'){const stats=talent?[[state.applications.length,'Propositions envoyées'],[myThreads().length,'Conversations'],[state.available?'Oui':'Bientôt','Disponible pour une mission']]:[[state.missions.length,'Missions créées'],[state.favorites.length,'Talents sélectionnés'],[myThreads().length,'Conversations']];return `<div class="dash-title"><h2>Votre activité, en un regard.</h2><a class="btn clay small" href="${talent?'#/missions':'#/publier'}">${icon('plus')}${talent?'Trouver une mission':'Nouvelle mission'}</a></div><div class="stats">${stats.map(([n,label])=>`<div class="stat"><strong>${n}</strong><span>${label}</span></div>`).join('')}</div><section class="panel"><h2>${talent?'Votre profil, votre meilleur point de départ.':'Prêt à rencontrer votre prochain talent ?'}</h2><p>${talent?'Votre profil de démonstration est créé. Vous pouvez maintenant consulter les missions et préparer une proposition personnalisée.':'Explorez les portfolios et sauvegardez vos profils favoris. Vous pourrez ensuite leur proposer directement une mission.'}</p><a class="text-link" style="margin-top:20px" href="${talent?'#/talent/mon-profil':'#/talents'}">${talent?'Voir mon profil':'Explorer les talents'} ${arrow()}</a></section><section class="panel"><h2>Votre prochaine action</h2><div class="activity-row"><div><strong>${talent?'Choisir une mission qui vous correspond':'Poser un brief clair'}</strong><small>${talent?'Comparez le budget, le contexte et les livrables.':'Un projet précis attire des propositions pertinentes.'}</small></div><a class="btn outline small" href="${talent?'#/missions':'#/publier'}">Commencer ${arrow()}</a></div><div class="activity-row"><div><strong>Suivre vos échanges</strong><small>${myThreads().length} conversation${myThreads().length>1?'s':''} dans votre espace.</small></div><button class="text-link" data-action="dash-tab" data-tab="messages">Ouvrir ${arrow()}</button></div></section><div class="demo-note">${icon('info')}Vos actions sont conservées dans ce navigateur. Les compteurs reflètent votre simulation ; aucune réponse de talent ou de recruteur n’est générée automatiquement.</div>`;}
if(dashTab==='favorites'){const list=state.favorites.map(talentById).filter(Boolean);return `<div class="dash-title"><h2>Votre sélection de talents</h2><a class="text-link" href="#/talents">Explorer ${arrow()}</a></div>${list.length?`<div class="talent-grid" style="grid-template-columns:repeat(auto-fit,minmax(min(100%,250px),1fr))">${list.map(talentCard).join('')}</div>`:empty('heart','Votre prochaine équipe commence ici.','Ajoutez des profils à votre sélection avec le cœur pour les retrouver et comparer leurs réalisations.',`<a class="btn clay" href="#/talents">Découvrir les talents ${arrow()}</a>`)}`;}
if(dashTab==='missions')return `<div class="dash-title"><h2>Vos missions</h2><a class="btn clay small" href="#/publier">${icon('plus')}Créer une mission</a></div>${state.missions.length?state.missions.map(m=>`<section class="panel"><div class="activity-row" style="padding-top:0"><div><strong><a href="#/mission/${esc(m.id)}">${esc(m.title)}</a></strong><small>${budget(m)} · ${esc(m.duration)}</small></div><span class="pill">Ouverte</span></div><p style="font-size:11px;margin:13px 0">${state.applications.filter(a=>a.missionId===m.id).length} proposition(s) reçue(s) dans votre simulation. Pour tester le parcours complet, passez côté talent et candidatez à cette mission.</p><button class="text-link" data-action="dash-tab" data-tab="received" style="margin-bottom:18px">Voir les propositions ${arrow()}</button><div style="display:flex;gap:20px"><a class="text-link" href="#/mission/${esc(m.id)}">Voir la mission ${arrow()}</a><button class="reset" data-action="delete-mission" data-id="${esc(m.id)}">Supprimer</button></div></section>`).join(''):empty('briefcase','Votre premier projet vous attend.','Créez une mission avec un brief, un budget et un calendrier pour tester le parcours recruteur.',`<a class="btn clay" href="#/publier">Décrire mon projet ${arrow()}</a>`)}`;
if(dashTab==='applications')return `<div class="dash-title"><h2>Vos propositions</h2><a class="text-link" href="#/missions">Explorer les missions ${arrow()}</a></div>${state.applications.length?state.applications.map(ap=>{const m=missionById(ap.missionId);return `<section class="panel"><div class="activity-row" style="padding-top:0"><div><strong><a href="#/mission/${esc(ap.missionId)}">${esc(m?.title||ap.missionTitle)}</a></strong><small>${money(ap.amount)} FCFA · ${esc(ap.delay)} · ${dateLabel(ap.createdAt)}</small></div><span class="pill">${ap.status==='selected'?'Profil retenu en démo':'Envoyée en démo'}</span></div><p style="margin-top:16px;white-space:pre-wrap">${esc(ap.message)}</p><button class="text-link" style="margin-top:17px" data-action="open-thread" data-id="${esc(ap.threadId)}">Retrouver la conversation ${arrow()}</button></section>`;}).join(''):empty('send','Votre expertise mérite une première proposition.','Repérez une mission et expliquez comment vous pouvez aider à la réaliser.',`<a class="btn clay" href="#/missions">Découvrir les missions ${arrow()}</a>`)}`;
if(dashTab==='received')return receivedView();
if(dashTab==='messages')return `<div class="dash-title"><h2>Vos conversations</h2></div>${inbox()}`;
if(dashTab==='profile')return `<div class="dash-title"><h2>${talent?'Votre profil talent':'Votre organisation'}</h2><button class="btn outline small" data-action="edit-profile">Modifier ${icon('design')}</button></div><section class="panel"><h2>${esc(a.name)}</h2><p>${esc(a.title)}${talent?'':' · '+esc(a.company)}</p><div class="inline-meta"><span>${icon('pin')}${esc(a.city)}, ${esc(a.country)}</span><span>${icon('mail')}${esc(a.email)}</span></div><hr class="side-divider"><p>${esc(a.bio)}</p>${talent?`<div style="margin-top:18px">${tags(a.skills.split(',').map(s=>s.trim()))}</div><label class="availability-toggle"><span>Disponible pour une nouvelle mission</span><input id="my-availability" type="checkbox" ${state.available?'checked':''}></label><a class="text-link" href="#/talent/mon-profil">Voir mon profil de démonstration ${arrow()}</a>${a.portfolio&&validWebsite(a.portfolio)?`<div style="margin-top:15px"><a class="text-link" href="${esc(a.portfolio)}" target="_blank" rel="noopener noreferrer">Ouvrir mon portfolio ${icon('up')}</a></div>`:''}`:`<p style="margin-top:15px"><strong>Secteur :</strong> ${esc(a.sector)}<br><strong>Besoin :</strong> ${esc(a.need)}</p>`}</section><section class="panel"><h2>Vos données de démonstration</h2><p>Vous pouvez reprendre cet essai sur ce navigateur ou l’effacer entièrement : profils talent et recruteur, favoris, missions, candidatures et messages.</p><button class="reset" style="margin-top:18px" data-action="reset-demo">Effacer ma démonstration</button></section>`;return '';}
function inbox(){const threads=myThreads();if(!threads.length)return empty('mail','Une conversation commence par une rencontre.','Proposez une mission à un talent ou candidatez à une mission pour démarrer un échange simulé.',`<a class="btn clay" href="${state.activeRole==='talent'?'#/missions':'#/talents'}">${state.activeRole==='talent'?'Explorer les missions':'Rencontrer les talents'} ${arrow()}</a>`);if(!threads.some(t=>t.id===activeThread))activeThread=threads[0].id;const t=threads.find(t=>t.id===activeThread);return `<div class="inbox"><div class="thread-list" aria-label="Conversations">${threads.map(th=>`<button class="thread-btn ${th.id===t.id?'active':''}" data-action="open-thread" data-id="${esc(th.id)}" aria-pressed="${th.id===t.id}"><strong>${esc(threadName(th))}</strong><small>${esc(th.subject.slice(0,65))}</small></button>`).join('')}</div><div class="thread-content"><h3>${esc(threadName(t))}</h3><p class="small muted">${esc(t.subject)}</p>${t.messages.map(m=>`<div class="bubble">${esc(m.text)}<small>${(m.role||t.role)===state.activeRole?'Vous':(m.role||t.role)==='talent'?'Talent (simulation)':'Recruteur (simulation)'} · ${dateLabel(m.date)} · Simulation locale</small></div>`).join('')}<div class="demo-note">Aucun destinataire réel ne reçoit ces messages. Sur une mission locale, vous pouvez changer de parcours pour simuler la réponse de l’autre rôle.</div><form class="message-form" id="message-form" data-thread="${esc(t.id)}"><label class="skip" for="message-text">Votre message</label><input id="message-text" name="message" required minlength="2" maxlength="2000" placeholder="Écrire un message de démonstration…" autocomplete="off"><button class="btn small" type="submit">${icon('send')}Envoyer</button></form></div></div>`;}
function openModal(html){focusReturn=document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><button class="modal-close" data-action="close-modal" aria-label="Fermer">${icon('x')}</button>${html}</section></div>`;document.body.style.overflow='hidden';const first=$('.modal input,.modal textarea,.modal select,.modal .btn');(first||$('.modal')).focus();}
function closeModal(){if(!$('#modal-root').innerHTML)return;$('#modal-root').innerHTML='';document.body.style.overflow='';if(focusReturn?.isConnected)focusReturn.focus();}
function needAccount(role,next){if(state.accounts[role]){state.activeRole=role;save();return false;}openModal(`<div class="eyebrow">${role==='talent'?'Votre expertise, votre proposition':'Le début d’une collaboration'}</div><h2 id="modal-title">${role==='talent'?'Créez votre profil pour vous présenter.':'Présentez-vous au talent.'}</h2><p>Quelques informations suffisent pour créer un espace ${role} de démonstration. Vous pourrez ensuite reprendre cette action.</p><button class="btn clay full" data-action="start-account" data-role="${role}" data-next="${esc(next)}">Créer mon espace ${arrow()}</button><div class="demo-note" style="margin-top:17px">Aucun compte réel n’est créé. Votre essai reste dans ce navigateur.</div>`);return true;}
function contact(id){const t=talentById(id);if(!t)return;if(needAccount('recruteur','/talent/'+id))return;openModal(`<div class="eyebrow">Le premier pas vers votre projet</div><h2 id="modal-title">Proposer une mission à ${esc(t.name.split(' ')[0])}.</h2><p>Présentez votre besoin, votre budget et les prochaines étapes. Votre message sera conservé dans votre espace de démonstration.</p><form id="contact-form" data-id="${esc(id)}">${field('subject','Votre projet *','text','','required minlength="5" maxlength="120" placeholder="Ex. : Refonte de notre application mobile"')}${field('budget','Budget prévu (FCFA) *','number','','required min="10000" max="100000000" step="1000" placeholder="300000"')}${textareaField('message','Votre message *','','required minlength="30" maxlength="2000" placeholder="Bonjour, nous avons découvert votre travail et aimerions vous présenter notre projet…"')}<div id="form-error" role="alert"></div><button class="btn clay full" type="submit">Envoyer dans la démo ${icon('send')}</button><p class="small muted" style="margin-top:12px">Aucun message n’est transmis à un destinataire réel.</p></form>`);}
function apply(id){const m=missionById(id);if(!m)return;if(state.applications.some(a=>a.missionId===id)){toast('Vous avez déjà envoyé une proposition pour cette mission.');return;}if(needAccount('talent','/mission/'+id))return;openModal(`<div class="eyebrow">Votre approche fait la différence</div><h2 id="modal-title">Votre proposition pour ${esc(m.company)}.</h2><p>${esc(m.title)}</p><form id="apply-form" data-id="${esc(id)}">${textareaField('message','Comment abordez-vous ce projet ? *','','required minlength="50" maxlength="2500" placeholder="Présentez votre approche, votre expérience pertinente et les étapes que vous proposez…"')}<div class="form-grid">${field('amount',`Votre proposition (FCFA${m.period?' / mois':''}) *`,'number','','required min="1000" max="100000000" step="1000" placeholder="300000"')}${field('delay','Votre délai *','text','','required minlength="2" maxlength="60" placeholder="Ex. : 3 semaines"')}</div><div class="demo-note" style="margin-bottom:18px">Budget indicatif de la mission : ${budget(m)}. Vous pouvez justifier une proposition différente dans votre message.</div><button class="btn clay full" type="submit">Envoyer ma proposition démo ${icon('send')}</button><p class="small muted" style="margin-top:12px">Aucune candidature n’est transmise à une entreprise réelle.</p></form>`);}
function submitContact(form){if(!form.reportValidity())return;const d={};mergeFormData(form,d);const t=talentById(form.dataset.id);if(!t||!state.accounts.recruteur||d.message.length<30||Number(d.budget)<10000)return;const thread={id:uid('thread'),role:'recruteur',with:t.name,subject:d.subject,talentId:t.id,messages:[{text:`${d.message}\n\nBudget proposé : ${money(d.budget)} FCFA`,date:new Date().toISOString()}]};state.threads.unshift(thread);activeThread=thread.id;state.activeRole='recruteur';save();closeModal();dashTab='messages';navigate('/espace');toast('Votre message de démonstration est enregistré.');}
function submitApply(form){if(!form.reportValidity())return;const d={};mergeFormData(form,d);const m=missionById(form.dataset.id);if(!m||!state.accounts.talent||state.applications.some(a=>a.missionId===m.id)||d.message.length<50||Number(d.amount)<1000)return;const thread={id:uid('thread'),role:'talent',roles:m.local?['talent','recruteur']:['talent'],recruiterWith:m.local?state.accounts.talent.name:null,with:m.company,subject:m.title,missionId:m.id,messages:[{text:`${d.message}\n\nProposition : ${money(d.amount)} FCFA${m.period||''}\nDélai : ${d.delay}`,date:new Date().toISOString(),role:'talent'}]};state.threads.unshift(thread);state.applications.unshift({id:uid('application'),missionId:m.id,missionTitle:m.title,talentName:state.accounts.talent.name,status:'received',message:d.message,amount:Number(d.amount),delay:d.delay,createdAt:new Date().toISOString(),threadId:thread.id});state.activeRole='talent';activeThread=thread.id;save();closeModal();dashTab='applications';navigate('/espace');toast('Votre proposition est enregistrée dans votre espace talent.');}
function submitMessage(form){if(!form.reportValidity())return;const message=form.elements.message.value.trim();if(message.length<2)return;const t=myThreads().find(x=>x.id===form.dataset.thread);if(!t)return;t.messages.push({text:message,date:new Date().toISOString(),role:state.activeRole});save();render(false);$('#message-text')?.focus();toast('Message ajouté à votre simulation.');}
function ownProfileHydration(){const t=talentById('mon-profil');if(!t)return;$('#profile-portfolio').innerHTML=`<h2>Votre portfolio</h2>${t.portfolio&&validWebsite(t.portfolio)?`<p>Découvrez les réalisations sur le portfolio lié à ce profil.</p><a class="btn outline" style="margin-top:18px" href="${esc(t.portfolio)}" target="_blank" rel="noopener noreferrer">Ouvrir mon portfolio ${icon('up')}</a>`:`<p>Ajoutez un lien vers vos réalisations pour donner à voir votre savoir-faire.</p><button class="btn outline" style="margin-top:18px" data-action="edit-profile" data-role="talent">Compléter mon profil ${arrow()}</button>`}`;$('.profile-side .side-actions').innerHTML=`<button class="btn clay" data-action="edit-profile" data-role="talent">Modifier mon profil ${icon('design')}</button><a class="btn outline" href="#/missions">Trouver une mission ${arrow()}</a>`;$('.profile-side .demo-note').textContent='Votre profil de démonstration est visible uniquement dans ce navigateur. Il n’est pas publié dans un annuaire réel.';}
function render(scroll=true){closeModal();const {parts,params}=routeInfo();const page=parts[0]||'';renderHeader();renderFooter();let html;switch(page){case '':html=home();break;case 'talents':case 'missions':if(scroll)filters={q:params.get('q')||'',category:CATEGORIES.includes(params.get('metier'))?params.get('metier'):'',country:'',available:false,sort:'recommended',mode:'',type:''};html=listing(page==='missions');break;case 'talent':html=profile(parts[1]);break;case 'mission':html=missionDetail(parts[1]);break;case 'inscription':html=parts[1]?signup(parts[1]):accountChoice();break;case 'publier':html=publishPage();break;case 'guide':html=guide();break;case 'a-propos':html=about();break;case 'confidentialite':html=privacy();break;case 'espace':if(params.get('onglet')&&scroll)dashTab=params.get('onglet');html=dashboard();break;default:html=notFound();}
$('#main').innerHTML=html;
const titles={'':'Le talent a de l’avenir','talents':'Trouver un talent','missions':'Les missions','guide':'Comment ça marche','inscription':'Créer mon espace','espace':'Mon espace','publier':'Publier une mission','a-propos':'Notre ambition','confidentialite':'Confidentialité'};
document.title=`${page==='talent'?(talentById(parts[1])?.name||'Profil'):page==='mission'?(missionById(parts[1])?.title||'Mission'):titles[page]||'Page introuvable'} — HerTalent Africa`;
if(page==='talents'||page==='missions')updateResults();if(page==='talent'&&parts[1]==='mon-profil'&&state.accounts.talent)ownProfileHydration();
if(scroll){window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});}}
document.addEventListener('click',e=>{
 const scrollEl=e.target.closest('[data-scroll]');if(scrollEl){e.preventDefault();const target=document.getElementById(scrollEl.dataset.scroll);target?.scrollIntoView({behavior:'smooth',block:'start'});target?.focus({preventScroll:true});return;}
 if(e.target.classList.contains('modal-backdrop')){closeModal();return;}
 const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id;switch(action){
 case 'menu':{const n=$('#nav');n.classList.toggle('open');el.setAttribute('aria-expanded',n.classList.contains('open'));break;}
 case 'favorite':{if(!talentById(id))break;const exists=state.favorites.includes(id);state.favorites=exists?state.favorites.filter(x=>x!==id):[...state.favorites,id];save();const y=window.scrollY;render(false);window.scrollTo(0,y);toast(exists?'Talent retiré de votre sélection.':'Talent ajouté à votre sélection. Retrouvez-le dans votre espace recruteur.');break;}
 case 'how':howRole=el.dataset.role;$('#how-content').innerHTML=howSteps();break;
 case 'filters':$('#filters').classList.toggle('open');el.setAttribute('aria-expanded',$('#filters').classList.contains('open'));break;
 case 'reset-filters':filters={q:'',category:'',country:'',available:false,sort:'recommended',mode:'',type:''};render(false);break;
 case 'project':{const t=talentById(id),p=t?.projects[Number(el.dataset.index)];if(p)openModal(`<div class="eyebrow">Portfolio de démonstration</div><h2 id="modal-title">${esc(p.title)}</h2><p>${esc(p.type)} · ${esc(t.name)}</p>${projectArt(p)}<p>${esc(p.description)}</p><button class="btn clay full" data-action="contact" data-id="${t.id}">Discuter d’un projet similaire ${arrow()}</button>`);break;}
 case 'contact':contact(id);break;
 case 'apply':apply(id);break;
 case 'select-applicant':{const ap=receivedApplications().find(a=>a.id===id);if(ap){ap.status='selected';save();render(false);toast('Profil retenu dans votre simulation. Convenez ensuite des modalités dans la conversation.');}break;}
 case 'close-modal':closeModal();break;
 case 'start-account':{const role=el.dataset.role;state.drafts.next=el.dataset.next||'/espace';if(missionWizard)state.drafts.mission=missionWizard;save();closeModal();if(state.accounts[role]){state.activeRole=role;const next=state.drafts.next;delete state.drafts.next;save();navigate(next);}else navigate('/inscription/'+role);break;}
 case 'signup-back':if(wizard&&wizard.step>1){wizard.step--;render(false);}break;
 case 'mission-back':if(missionWizard&&missionWizard.step>1){missionWizard.step--;state.drafts.mission=missionWizard;save();render(false);}break;
 case 'dash-tab':dashTab=el.dataset.tab;render(false);break;
 case 'open-thread':if(myThreads().some(t=>t.id===id)){activeThread=id;dashTab='messages';render(false);}break;
 case 'switch-role':if(state.accounts[el.dataset.role]){state.activeRole=el.dataset.role;dashTab='overview';save();navigate('/espace');}break;
 case 'choose-role':state.activeRole=null;save();navigate('/inscription');break;
 case 'edit-profile':{const role=el.dataset.role||state.activeRole;if(state.accounts[role]){wizard={role,step:1,data:{...state.accounts[role]}};navigate('/inscription/'+role);}break;}
 case 'delete-mission':openModal(`<h2 id="modal-title">Supprimer cette mission de démonstration ?</h2><p>Le brief sera retiré des missions conservées dans ce navigateur.</p><button class="btn clay full" data-action="confirm-delete-mission" data-id="${esc(id)}">Supprimer la mission</button>`);break;
 case 'confirm-delete-mission':state.missions=state.missions.filter(m=>m.id!==id);save();closeModal();render(false);toast('Mission retirée de la démonstration.');break;
 case 'reset-demo':openModal(`<h2 id="modal-title">Repartir d’une page blanche ?</h2><p>Les espaces talent et recruteur, les favoris, les brouillons, les missions, les propositions et les messages de ce navigateur seront effacés. Les données d’exemple resteront disponibles.</p><button class="btn clay full" data-action="confirm-reset">Effacer les données de mon essai</button><button class="btn outline full" style="margin-top:10px" data-action="close-modal">Conserver mon essai</button>`);break;
 case 'confirm-reset':state=freshState();wizard=null;missionWizard=null;dashTab='overview';activeThread=null;save();closeModal();navigate('/');toast('Votre démonstration a été réinitialisée.');break;
 case 'about-demo':openModal(`<div class="eyebrow">Première version privée</div><h2 id="modal-title">Un prototype à explorer, vraiment.</h2><p>Recherchez un talent, ouvrez son portfolio, créez un espace, préparez une mission et envoyez une proposition simulée.</p><div class="demo-note">Les profils et missions d’exemple sont fictifs. Les actions sont sauvegardées uniquement dans ce navigateur. Aucun compte réel, paiement, e-mail ou message externe n’est créé.</div><a class="btn clay full" href="#/guide" style="margin-top:20px">Explorer les parcours ${arrow()}</a>`);break;
 }
});
document.addEventListener('input',e=>{if(e.target.id==='search'){filters.q=e.target.value;updateResults();}const form=e.target.closest('form');if(form?.id==='signup-form'&&wizard){mergeFormData(form,wizard.data);state.drafts['signup-'+wizard.role]=wizard.data;save();}if(form?.id==='publish-form'&&missionWizard){mergeFormData(form,missionWizard.data);state.drafts.mission=missionWizard;save();}});
document.addEventListener('change',e=>{if(e.target.dataset.filter){const k=e.target.dataset.filter;filters[k]=e.target.type==='checkbox'?e.target.checked:e.target.value;updateResults();}if(e.target.id==='my-availability'){state.available=e.target.checked;if(state.accounts.talent)state.accounts.talent.availability=state.available?'Disponible maintenant':'Bientôt disponible';save();toast('Votre disponibilité de démonstration est mise à jour.');}});
document.addEventListener('submit',e=>{const f=e.target;if(!['signup-form','publish-form','contact-form','apply-form','message-form'].includes(f.id))return;e.preventDefault();if(f.id==='signup-form')submitSignup(f);if(f.id==='publish-form')submitMission(f);if(f.id==='contact-form')submitContact(f);if(f.id==='apply-form')submitApply(f);if(f.id==='message-form')submitMessage(f);});
document.addEventListener('keydown',e=>{const modal=$('.modal');if(!modal)return;if(e.key==='Escape'){e.preventDefault();closeModal();}if(e.key==='Tab'){const controls=$$('a[href],button:not([disabled]),input,select,textarea,[tabindex="0"]',modal);const first=controls[0],last=controls[controls.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('hashchange',()=>render());
bootstrap();
